design_artifacts.class_diagram_mermaid:
```mermaid
classDiagram
    class Tokenizer {
        +tokenize(expr: str) List[Token]
    }
    class Parser {
        +parse(tokens: List[Token]) ASTNode
    }
    class Evaluator {
        +evaluate(node: ASTNode) Decimal
    }
    class Calculator {
        +calculate(expr: str) str
    }
    class Token {
        +type: TokenType
        +value: str
    }
    class ASTNode {
        <<abstract>>
    }
    class NumberNode {
        +value: Decimal
    }
    class BinaryOpNode {
        +left: ASTNode
        +right: ASTNode
        +op: str
    }
    Tokenizer --> Token
    Parser --> Token
    Parser --> ASTNode
    Evaluator --> ASTNode
    Calculator --> Tokenizer
    Calculator --> Parser
    Calculator --> Evaluator
    ASTNode <|-- NumberNode
    ASTNode <|-- BinaryOpNode
```

